for(const [id,title,substance,eq,obs,product] of [
 ['carbon-oxygen','木炭在空气和氧气中燃烧','C','C+O₂ → CO₂','空气中红热，氧气中更明亮，充分燃烧生成CO₂','二氧化碳'],
 ['sulfur-oxygen','硫在空气和氧气中燃烧','S','S+O₂ → SO₂','空气中呈淡蓝色火焰，氧气中更明显地呈蓝紫色火焰','二氧化硫'],
 ['iron-oxygen','铁丝在氧气中燃烧','Fe','3Fe+2O₂ → Fe₃O₄','细铁丝在氧气中燃烧时火星四射，生成黑色固体','四氧化三铁']]) {
 add(id,2,title,'burn-oxygen',[pick('atmosphere','气氛',[['air','空气'],['oxygen','氧气']]),num('mass','燃料质量','g',.1,3,.1,1),yes('ignited','已经适当引燃')],[`比较${substance}在不同氧含量环境下的现象。`,'燃烧匙或坩埚钳|氧气集气瓶|指定少量试样','先观察在空气中的现象。|在教师指导下比较氧气中的现象。|根据产物证据书写反应式。',obs,`适宜条件下反应生成${product}。`,eq+'，条件为点燃。','氧气支持燃烧，并不说明氧气本身是燃料。',`本实验生成的主要产物叫什么？`,product],{substance,pepEvidence:'上册实验2-2、2-3、2-4',modelNote:'燃烧现象定性比较；产物量仅在指定充分供氧的理想完全反应条件下计算。',safety:[substance==='S'?'硫燃烧只由教师在通风橱或排风设备下演示。':'教师指导下操作；铁丝燃烧的瓶底预先放少量水以防灼裂。']});
}
add('permanganate',2,'加热高锰酸钾制氧气','permanganate',[num('mass','KMnO₄质量','g',.316,6.32,.316,3.16),yes('heated','加热'),yes('cotton','试管口放疏松棉花')],['认识固体加热型制气装置及操作顺序。','高锰酸钾|试管|铁架台|棉花|酒精灯|导管|水槽','检查气密性后装药并使管口略向下。|加热，连续气泡后收集。|结束先移出水中导管，再停止加热。','加热产生氧气。|疏松棉花能减少粉末进入导管。','2KMnO₄ → K₂MnO₄+MnO₂+O₂↑，条件为加热。','开始排出的气体混有装置内空气。','先停热后移导管可能发生倒吸。','3.16 gKMnO₄理论上可生成多少氧气？','3.16×32/316=0.32 g。'],{pepEvidence:'上册实验2-5',workedExample:calc('KMnO₄为3.16 g。','2KMnO₄ → K₂MnO₄+MnO₂+O₂↑；316∶32。','3.16×32/316=0.32 g。','完全反应的理论氧气质量为0.32 g。'),safety:['氧化性试剂由教师管理；加热装置使用结束按先撤导管后停热的顺序。']});
add('limewater',6,'二氧化碳与澄清石灰水','limewater',[num('co2','累计通入CO₂质量','g',0,.176,.0044,.044),num('lime','溶液中Ca(OH)₂质量','g',.037,.296,.037,.074)],['观察二氧化碳少量与过量时的区别。','澄清石灰水|二氧化碳|试管|导管','向石灰水中逐渐通入CO₂。|记录出现浑浊的阶段。|继续通入足量CO₂，观察后续变化。','先生成白色CaCO₃沉淀。|继续通入过量CO₂时沉淀可溶解。','CO₂的用量影响最终产物及现象。','CO₂+Ca(OH)₂ → CaCO₃↓+H₂O。|CaCO₃+CO₂+H₂O → Ca(HCO₃)₂。','没有浑浊不能在任何条件下排除CO₂，需考虑试剂失效和气体过量。','0.074 gCa(OH)₂最多可形成多少CaCO₃？','按74∶100计算，最多0.100 g。'],{modelNote:note+'忽略溶度积与气体传质，仅按两个反应的先后计量估算沉淀质量。'});
add('co2-extinguish',6,'倾倒二氧化碳与阶梯蜡烛','co2-physical',[pick('mode','观察方式',[['candle','阶梯蜡烛']]),pick('gas','气体',[['co2','二氧化碳'],['air','空气']])],['从先后熄灭顺序推断气体性质。','盛有CO₂的集气瓶|烧杯|高低两支蜡烛','点燃两支高低不同蜡烛。|沿烧杯壁缓慢倾入气体。|观察两支蜡烛的状态。','CO₂逐渐积聚时，低处蜡烛通常先熄灭。','在该条件下CO₂密度比空气大且不支持蜡烛燃烧。','结论要同时联系熄灭与先后顺序。','CO₂并非不能支持任何物质的燃烧。','只观察到蜡烛熄灭能说明密度较大吗？','不能，还要结合低处先熄灭等观察及装置条件。'],{pepEvidence:'上册实验6-3'});
add('co2-solubility',6,'二氧化碳的溶解与软瓶变化','co2-physical',[pick('mode','观察方式',[['bottle','软塑料瓶']]),pick('gas','气体',[['co2','二氧化碳'],['air','空气']]),yes('water','加入水并振荡')],['分析气体被水吸收后瓶内外压强差的证据。','充气软塑料瓶|水','向瓶中加入适量水。|立即密封并轻轻振荡。|比较瓶体形状。','装CO₂并加水的软瓶可变瘪。','气体被吸收后，瓶内压强降低，外界大气压使瓶变瘪。','瓶变瘪可说明气体减少，但不能仅凭此确定化学变化。','不能说瓶子被内部“吸力”吸瘪。','为什么相同装置加NaOH还需要水对照？','水本身也能吸收CO₂，需要分辨化学吸收的额外作用。'],{pepEvidence:'上册实验6-4',modelNote:'形变为定性示意，不提供假定瓶壁刚度下的精确压强。'});
add('carbon-cuo',6,'木炭还原氧化铜','reaction',reactionControls('CuO质量','碳质量',1.6,.12),['用颜色和气体检验判断还原反应。','干燥CuO与炭粉|耐热试管|加热设备|澄清石灰水','教师加热混合物并观察。|用石灰水检验产生的气体。|按要求先移导管后停热，并避免热铜重新氧化。','黑色混合物中可出现红色铜。|产生的CO₂使石灰水变浑浊。','高温下碳能夺取氧化铜中的氧。','2CuO+C → 2Cu+CO₂↑。','应描述颜色变化，不以“生成铜”代替实验现象。','1.60 gCuO充分反应最多得到多少铜？','1.60×128/160=1.28 g铜。'],{reaction:'carbon-cuo',pepEvidence:'上册实验6-2',safety:['高温还原仅由教师在通风条件下演示，按规定处置残余物。']});
add('iron-smelting',8,'一氧化碳还原氧化铁的模型','reaction',reactionControls('Fe₂O₃质量','CO质量',1.6,.84),['把冶炼中的氧转移与质量计算联系。','密闭演示装置示意|氧化铁|CO气路|尾气处理示意','在模拟中核对装置及尾气处理。|观察高温反应前后固体组成。|由配平方程式计算理论铁产量。','红棕色固体逐渐转变为铁。|反应生成CO₂。','Fe₂O₃+3CO → 2Fe+3CO₂，条件为高温。','计算矿石产铁需先扣除杂质。','CO有毒，不把模型当作家庭操作指南。','1.60 g纯Fe₂O₃理论上可得到多少铁？','1.60×112/160=1.12 g。'],{reaction:'iron-smelting',modelNote:note+'理想化纯氧化铁计量，真实高炉还有多种反应与损耗。',safety:['一氧化碳有毒，此项为模拟；真实演示须具备密闭供气和尾气处理。']});
add('metal-displacement',8,'金属与盐溶液的置换','displacement',[pick('pair','组合',[['fe-cu','铁与硫酸铜'],['cu-ag','铜与硝酸银'],['cu-fe','铜与硫酸亚铁']]),...reactionControls('金属质量','盐的溶质质量',.56,1.6)],['通过置换现象比较金属活动性。','铁、铜片|CuSO₄、AgNO₃或FeSO₄溶液|试管','打磨样品。|将金属放入指定盐溶液。|比较表面沉积与溶液颜色。','铁在CuSO₄中表面出现红色物质。|铜在AgNO₃中可析出银。|铜通常不能置换FeSO₄中的铁。','较活泼金属可置换较不活泼金属盐溶液中的金属。','Fe+CuSO₄ → FeSO₄+Cu。','盐溶液颜色变浅不一定代表盐已完全消耗。','0.56 g铁与足量CuSO₄反应，生成多少铜？','0.56×64/56=0.64 g。'],{directoryNumbers:[33],safety:['含重金属的溶液与残渣集中回收。']});
add('alloy',8,'比较合金与纯金属的性质','alloy',[pick('pair','比较对象',[['copper-brass','铜与黄铜'],['tin-solder','锡与焊锡合金']]),pick('test','比较项目',[['hardness','相互刻划'],['melting','熔化先后']])],['理解合金性质与组成有关。','纯金属与合金样品|刻划与加热演示装置','比较样品颜色。|采用相同方式比较刻划痕迹。|根据教师演示比较熔化先后。','常见黄铜通常比纯铜硬。|某些合金熔点低于组成它的纯金属。','合金性能由组成、结构及加工条件决定。','合金属于混合物；性能规律通常有适用范围。','不可说所有合金的所有性能都优于纯金属。','为什么说制造材料时应综合考虑性质和成本？','用途要求不同，需在硬度、耐腐蚀性、加工性、成本等之间作选择。'],{modelNote:'常见教学样品的定性比较，未规定配比的合金不显示精确硬度或熔点。'});
const solControls=[pick('solute','溶质',[['KNO3','硝酸钾'],['NaCl','氯化钠']]),num('temperature','温度','℃',0,80,5,20),num('soluteMass','加入溶质质量','g',0,100,1,40),num('water','水质量','g',10,200,10,100)];
add('saturation',9,'饱和溶液与溶解度','solubility',solControls,['用温度和溶剂量判断能否继续溶解。','KNO₃或NaCl|水|烧杯|温度计','在给定温度与水量下逐渐加入溶质。|观察是否有固体剩余。|单独改变温度或水量再次比较。','达到溶解能力上限后，继续加固体会有剩余。|KNO₃溶解度随温度变化较明显。','饱和必须说明温度与溶剂量。','S是一定温度下100 g溶剂达到饱和时溶解的质量。','浓溶液不一定饱和；饱和溶液不一定很浓。','20 ℃时100 g水最多溶解31.6 gKNO₃，加入40 g会怎样？','形成131.6 g饱和溶液，剩余8.4 g固体。'],{modelNote:note+'采用常用课堂溶解度表，表间线性插值；这些数值为模型参考表，非本次实测。',workedExample:calc('20 ℃，水100 g，KNO₃加入40 g，S=31.6 g/100 g水。','最多溶解质量=S×m(水)/100。','溶解31.6 g；未溶40−31.6=8.4 g；溶液质量131.6 g。','为饱和溶液，底部剩余8.4 g固体。')});
add('crystallization',9,'冷却结晶与溶解度曲线','crystallization',[pick('solute','溶质',[['KNO3','硝酸钾'],['NaCl','氯化钠']]),num('hot','起始饱和温度','℃',20,80,10,60),num('cold','冷却后温度','℃',0,60,10,20),num('water','水质量','g',20,200,10,100)],['从两温度的溶解度差估算析晶量。','饱和溶液|烧杯|温度计|过滤装置','制得指定温度的饱和溶液。|不蒸发水地冷却。|分离晶体并比较母液。','降温后溶解度降低的物质可析晶。','理想析晶质量由溶解度差和水量确定。','结晶后的母液通常仍含溶质。','不能把冷却后的溶液当成纯水。','100 g水配成60 ℃KNO₃饱和溶液，冷至20 ℃理论析晶多少？','按110−31.6计算，可析出78.4 g晶体。'],{modelNote:note+'采用参考溶解度表并忽略过饱和及水损失；冷却温度高于起始温度时不算负析晶量。'});
add('emulsion',9,'乳化作用与溶解的区别','emulsion',[yes('detergent','加入洗涤剂'),yes('shake','振荡'),pick('stage','观察时机',[['during','刚振荡后'],['rest','静置后']])],['区分暂时分散、乳化与真正溶解。','水|食用油|洗涤剂|试管','水中加入少量油，观察分层。|振荡后观察并静置。|加洗涤剂后重复比较。','无洗涤剂时油滴分散后易重新分层。|加洗涤剂可形成较稳定的乳浊液。','乳化是把油分散成小液滴，不等于油以分子形式完全溶解。','洗涤剂去油污与汽油溶解油污原理不同。','均匀看起来相同不代表体系都是溶液。','洗涤剂使油污“消失”就说明油完全溶解了吗？','不是；油可能被乳化成细小液滴后随水带走。'],{modelNote:'液滴为乳化原理示意，不模拟具体表面活性剂的稳定时间。'});
add('lime-heat',7,'生石灰与水反应的放热','reaction',reactionControls('CaO质量','可供水质量',.56,1.8),['观察化学变化与能量变化同时发生。','少量生石灰|水|耐热容器|温度计','先记录环境温度。|教师将少量生石灰与水接触。|记录反应与温度变化的方向。','固体发生变化，温度明显升高。','CaO+H₂O → Ca(OH)₂，反应放热。','化学反应伴随能量变化。','生石灰、熟石灰、石灰石不是同一种物质。','0.56 gCaO完全反应得到多少Ca(OH)₂？','0.56×74/56=0.74 g。'],{reaction:'lime-water',pepEvidence:'上册实验7-1',safety:['生石灰有腐蚀性，遇水放热；教师少量演示，避免飞溅。']});
add('methane',7,'甲烷燃烧产物的检验','reaction',reactionControls('甲烷质量','氧气质量',.16,.64),['从水与CO₂的检验分析天然气主要成分的燃烧。','甲烷燃烧演示装置|干燥烧杯|石灰水','在教师预先检查后的装置中观察火焰。|先用干燥冷烧杯检验水。|再用石灰水检验CO₂。','充分燃烧通常有蓝色火焰。|冷烧杯有水珠，石灰水变浑浊。','CH₄+2O₂ → CO₂+2H₂O，条件为点燃。','燃料不充分燃烧可能产生CO等有害物。','产物检验先水后CO₂，避免石灰水带来的水影响判断。','0.16 g甲烷完全燃烧需多少氧气？','0.16×64/16=0.64 g氧气。'],{reaction:'methane',pepEvidence:'上册实验7-2',modelNote:note+'只计算完全燃烧；氧不足时提示模型边界，不伪造不完全燃烧比例。',safety:['可燃气体验纯与点火由教师完成，不进行家庭气路改装。']});
add('carbonate-test',10,'碳酸盐与稀酸的检验','reaction',[pick('reaction','试样',[['sodium-carbonate','碳酸钠'],['bicarbonate','碳酸氢钠'],['carbonate-acid','碳酸钙']]),...reactionControls('试样质量','HCl溶质质量',1.06,.73)],['通过气体及后续检验判断碳酸盐类。','待测盐|稀盐酸|澄清石灰水|试管|导管','取少量样品加稀盐酸。|将产生气体通入石灰水。|将两步证据合并分析。','含碳酸根或碳酸氢根的样品可放出CO₂。','产生气体并使石灰水浑浊是相关离子检验的重要证据。','不同碳酸盐生成相同质量CO₂所需样品量不同。','该检验不能独自区分CO₃²⁻和HCO₃⁻。','只看到加酸有气泡够不够？','不够，还应检验气体是否为CO₂，金属与酸也可能产生气泡。'] );
add('precipitation',10,'复分解反应与沉淀生成','reaction',[pick('reaction','反应组合',[['carbonate-calcium','Na₂CO₃与CaCl₂'],['copper-hydroxide','CuSO₄与NaOH'],['sulfate-barium','Na₂SO₄与BaCl₂']]),...reactionControls('第一种溶质质量','第二种溶质质量',1.06,1.11)],['联系离子组合、生成沉淀与可观察现象。','指定稀盐溶液|点滴板|滴管','取少量两种溶液。|滴加混合并观察是否生成固体。|根据产物溶解性写出方程式。','碳酸钙和硫酸钡沉淀为白色。|氢氧化铜沉淀为蓝色。','生成难溶物等可使某些复分解反应进行。','Na₂CO₃+CaCl₂ → CaCO₃↓+2NaCl。','两种溶液混合不是必然反应。','1.06 gNa₂CO₃与足量CaCl₂最多生成多少CaCO₃？','按106∶100计算，为1.00 g。'],{safety:['含钡和含铜的试剂及废物由教师管理，实验后集中回收。']});
add('dilution',9,'溶液稀释与溶质守恒','dilution',[num('mass','原溶液质量','g',10,200,5,50),num('percent','原质量分数','%',1,20,1,10),num('water','加入水质量','g',0,200,5,50)],['用溶质质量不变计算稀释结果。','已知质量分数NaCl溶液|水|烧杯|天平','计算原溶质质量。|称取规定质量水并混合。|计算新溶液总质量和质量分数。','加水后溶液总质量增大，溶质质量不变。','稀释不改变溶质质量，降低质量分数。','m₁w₁=m₂w₂。','不要将体积直接相加当作精确质量。','50 g的10%溶液加50 g水后质量分数是多少？','溶质5 g，总质量100 g，质量分数5%。'],{workedExample:calc('50 g、10%的NaCl溶液加50 g水。','稀释前后溶质质量保持不变。','盐5 g；总质量100 g；w=5/100×100%=5%。','所得溶液质量分数为5%。')});
add('hardness',4,'硬水与软水的比较','hardness',[pick('water','水样',[['soft','软水'],['hard','硬水'],['boiled','煮沸后部分软化的水']]),num('soap','肥皂液相对加入量','份',1,5,1,2)],['用相同肥皂液观察硬度差异。','水样|肥皂液|试管','取等体积水样。|加入等量肥皂液并用相同方法振荡。|比较泡沫与浮渣。','软水较易起泡。|硬水常产生较多浮渣。','硬水含较多可溶性钙镁化合物。','煮沸能降低部分硬度；蒸馏可进一步分离不挥发盐。','不能认为所有硬度都能靠煮沸完全去除。','为什么要求肥皂液用量相同？','起泡受肥皂用量影响，需控制用量才能比较水样。'],{modelNote:'定性比较，不把泡沫高度换算为未经标定的硬度。'});
add('copper-hydroxide-heat',1,'氢氧化铜沉淀的生成与受热变化','copper-heat',[num('salt','CuSO₄质量','g',.16,1.6,.16,.8),yes('heat','生成沉淀后加热')],['观察先沉淀后分解的连续变化。','CuSO₄溶液|足量NaOH溶液|试管|加热设备','滴加NaOH得到沉淀。|记录沉淀颜色。|教师温热后再次比较。','先生成蓝色Cu(OH)₂。|加热后逐渐出现黑色CuO。','Cu(OH)₂受热可分解为CuO和水。','CuSO₄+2NaOH → Cu(OH)₂↓+Na₂SO₄；Cu(OH)₂ → CuO+H₂O。','不是所有沉淀受热都以同样方式分解。','蓝色沉淀变黑属于哪类变化？','生成了氧化铜等新物质，是化学变化。'],{pepEvidence:'上册实验1-5',safety:['加热在教师指导下进行；铜盐废液集中回收。']});
// Cross-disciplinary practice uses explicit design or entered data, never invented field measurements.
add('air-station',2,'微型空气质量检测站：采样与比较','air-station',[num('sampleA','地点A输入的PM₂.₅读数','μg/m³',0,200,1,25),num('sampleB','地点B输入的PM₂.₅读数','μg/m³',0,200,1,45),yes('sameTime','两地同一时段且同仪器测量')],['练习传感器采样方案与数据比较。','PM传感器|记录设备|时间记录表','校准或核对仪器说明。|在相同时段按一致方式采样。|记录多次数据与环境条件，再比较。','页面读数由输入设定，不是当前位置空气测量。','一次读数不能代表长期空气质量。','比较需记录地点、时间、仪器与重复样本。','PM₂.₅单项数值不是综合AQI；不得自动给出未经标准换算的等级。','A读数25，B读数45，能说B长期一定更差吗？','不能，只能说明这组可比样本中B高20 μg/m³，长期判断需要更多记录。'],{kind:'拓展探究',pepCross:1,modelNote:'教学数据录入模型，不访问真实传感器，不给出空气健康等级。'});
add('atom-model',3,'制作模型理解分子、原子与元素','atom-model',[pick('molecule','分子模型',[['H2O','水分子'],['CO2','二氧化碳分子'],['O2','氧分子'],['CH4','甲烷分子']]),num('count','分子个数','个',1,5,1,2)],['从模型中区分原子数、分子数与元素种类。','不同颜色小球|连接杆|标签','选择分子并确定化学式。|按原子个数比例组装。|比较多个分子的原子总数。','水分子模型含2个氢原子与1个氧原子。','化学式下标描述一个分子中相应原子数。','元素属于种类概念，通常说“某元素”而不说“几个元素”。','球的颜色与比例只是模型约定。','2个水分子共含多少氢原子和氧原子？','含4个氢原子和2个氧原子，氢氧元素仍只有2种。'],{kind:'拓展探究',pepCross:2,modelNote:'球棍模型用于组成计数，不代表原子真实大小、颜色或完整电子结构。'});
add('water-filter-design',4,'设计净水器并判断处理边界','purification',[pick('method','净水模块',[['filter','滤纸或细砂过滤'],['adsorb','活性炭吸附'],['distill','蒸馏对照']]),pick('impurity','待处理物',[['sand','泥沙'],['dye','色素'],['salt','可溶性盐']])],['根据水质需求选择处理模块。','透明容器|滤纸或砂层|活性炭|水样|记录表','明确要除去的杂质。|选择对应模块并设置原水对照。|比较处理效果，指出仍需解决的问题。','过滤对悬浮颗粒有效。|活性炭对部分色素有效。','器件设计应对应杂质类型和评价指标。','实验室模型仅解释净化原理。','透明不等于可饮用。','若目标是去除溶解食盐，只加滤纸够吗？','不够，需采用适用的分离方法，如蒸馏。'],{kind:'拓展探究',pepCross:3,safety:['自制装置出水不饮用。']});
add('oxygen-design',5,'按需求设计简易供氧器的理论用量','oxygen',oxyControls,['将供氧需求与反应计量、可控性联系。','过氧化氢分解装置示意|气体收集器|检验工具','先确定模拟需要的氧气量。|根据浓度反推试剂用量。|比较催化、气密性与气体检验要求。','同质量分数下，溶液量决定理论供氧总量。','设计需同时考虑产量、速率、纯度与安全。','化学计量产量不等于装置实际收集量。','本装置不能作为医疗或救生供氧设备。','理论需要0.32 g氧气，3.4%过氧化氢溶液至少需多少？','需过氧化氢0.68 g，因此溶液质量0.68÷3.4%=20 g。'],{kind:'拓展探究',pepCross:4,modelNote:note+'仅作课堂设计计算，不用于人体供氧。'});
add('carbon-budget',6,'基于碳中和理念比较低碳方案','carbon-budget',[num('energy','每日用电量','kWh',0,30,.5,5),num('factor','题设电力排放因子','kg CO₂/kWh',0,1.5,.05,.5),num('saved','方案节电比例','%',0,80,5,20)],['用明确边界与给定因子比较方案。','用电记录|题设排放因子|计算表','确定只比较用电环节。|输入同一时间范围的用电量和给定因子。|计算方案前后差异并注明未计入项目。','同一排放因子下，节电减少对应估算排放。','量化结论依赖系统边界与因子来源。','排放量=活动量×排放因子。','示例因子不是全国统一实时因子，也不是完整生命周期核算。','每日5 kWh、因子0.5 kg/kWh，节电20%可少排多少？','按题设估算减少5×20%×0.5=0.5 kg CO₂/日。'],{kind:'拓展探究',pepCross:5,modelNote:'输入项为题设，不是官方实时碳核算；只比较用电环节。'});
add('fuel-survey',7,'比较家庭燃料的使用方案','fuel-survey',[pick('fuel','方案',[['gas','燃气灶'],['electric','电加热']]),num('demand','所需有效热量','MJ',1,20,1,5),num('efficiency','题设热效率','%',20,95,5,50)],['区分输入能量与有效利用能量。','家庭燃料调查表|设备说明|给定效率','调查燃料来源与设备。|确定比较相同的有效热量。|用给定效率计算输入能量，另评估污染与使用条件。','效率越高，实现相同有效热量所需输入越少。','燃料选择还需考虑来源、成本与污染。','效率=有效能量/输入能量。','不能仅凭电器无现场废气断定全生命周期零排放。','需5 MJ有效热量，效率50%，输入多少？','输入能量5÷50%=10 MJ。'],{kind:'拓展探究',pepCross:6,modelNote:'热效率由用户作为题设输入；不提供未经测量的某型号实际效率。'});
add('recycling',8,'垃圾分类与金属回收设计','recycling',[pick('material','物品',[['iron','铁罐'],['aluminium','铝罐'],['battery','废电池'],['glass','玻璃瓶'],['paper','废纸']]),pick('method','初步分选',[['magnet','磁选'],['manual','按类别分选']])],['利用材料性质提出回收流程。','干净样品或图片|磁铁|分类标签','辨认材料。|选择磁选或分类收集。|考虑污染物和当地分类要求。','铁罐可被磁铁吸引。|铝罐通常不被普通磁铁吸引。','一种分选方法不能区分所有材料。','回收可减少原生资源消耗；混合材料需进一步处理。','废电池不得拆解或用酸浸泡。','不能被磁铁吸引的罐子一定不是金属吗？','不是，铝等金属通常不被普通磁铁吸引。'],{kind:'拓展探究',pepCross:7,safety:['废电池仅用图片辨识，交指定回收渠道，不拆解。']});
add('sea-salt',9,'海水制盐的理想蒸发模型','sea-salt',[num('mass','盐水质量','g',100,1000,50,500),num('percent','题设NaCl质量分数','%',1,10,.5,3),num('evaporated','蒸发的水','g',0,900,10,300)],['追踪水减少、饱和与析盐的关系。','盐水|蒸发容器|称量记录','先根据题设估算盐和水质量。|逐渐蒸发水并记录。|达到饱和后观察晶体出现。','开始只使溶液变浓。|超过溶解能力后析出盐。','制盐过程中溶质和溶剂的去向不同。','海水还含多种盐，本页只用NaCl简化。','蒸发全部水的理论残留物不等于工业纯NaCl。','500 g、3%的NaCl盐水完全蒸干，理想残留多少盐？','500×3%=15 g。'],{kind:'拓展探究',pepCross:8,modelNote:note+'只考虑NaCl和水，20 ℃溶解度取36.0 g/100 g水；蒸发量自动限制在原水量以内。'});
add('aerospace',11,'航天材料与能源的证据比较','materials',[pick('material','材料',[['aluminium','铝合金'],['composite','碳纤维复合材料'],['ceramic','耐热陶瓷'],['hydrogen','氢能系统']]),pick('need','主要需求',[['light','减轻结构质量'],['heat','高温防护'],['energy','储存和供给能量']])],['根据使用需求提出材料选择理由和待验证指标。','材料资料卡|用途图片|对比表','明确载荷或热环境需求。|比较材料的结构、耐热、储能等特点。|列出需要查证的性能数据与来源。','不同材料承担不同任务。','选择须同时考虑适用环境、结构要求和代价。','复合材料通常由不同材料组合，不等于合金。','“先进”不能替代具体性能证据。','结构轻量化和高温隔热能否只用同一个指标评价？','不能，两者需分别比较密度、强度、耐热与隔热等指标。'],{kind:'拓展探究',pepCross:10,modelNote:'材料选择的定性证据卡，不伪造特定航天器参数或认证结论。'});
add('protein',11,'区分常见纤维的组成与现象','materials',[pick('material','纤维',[['wool','羊毛'],['cotton','棉'],['polyester','涤纶']]),pick('need','观察方式',[['look','观察纤维外观'],['burn','教师演示燃烧对照']])],['利用多种证据辨别纤维类型。','纤维样品|放大镜|教师燃烧演示资料','先比较外观。|观看教师控制下的燃烧现象。|结合灰烬和成分分析，避免仅凭单一气味判断。','羊毛为蛋白质纤维。|棉主要为纤维素。|涤纶属于合成纤维。','材料鉴别应结合多个特征。','羊毛燃烧与烧焦羽毛气味相似，但不能直接嗅吸烟气。','混纺材料可能同时具有多种表现。','只看颜色就能判断棉和涤纶吗？','不能，颜色可由染料造成，应结合材料组成和其他检验。'],{modelNote:'现象为典型材料的定性提示，混纺品不保证符合单一材料特征。',safety:['燃烧鉴别由教师少量演示，勿直接吸入烟气。']});
add('plastic',11,'认识塑料的受热变化','materials',[pick('material','塑料类型',[['thermoplastic','热塑性塑料示例'],['thermoset','热固性塑料示例']]),pick('need','条件',[['cold','常温'],['heat','受热']])],['比较不同高分子材料受热表现。','材料样品|教师演示资料','观察常温材料。|比较教师展示的受热现象。|联系重复加工与回收方式。','热塑性材料受热可软化。|热固性材料通常不再熔融成原状。','材料内部结构影响受热表现和加工方式。','不是所有塑料都能靠加热重新成型。','软化不是任意高温都安全，过热可能分解。','为什么不能把所有废塑料混在一起直接加热？','种类及添加物不同，受热行为和分解风险不同，回收需要分类和专业处理。'],{modelNote:'只作材料分类，不计算未经给定牌号的精确软化温度。',safety:['不在家中燃烧或熔融未知塑料。']});
add('hydrogen-burn',4,'氢气燃烧与水的组成证据','reaction',reactionControls('H₂质量','O₂质量',.04,.32),['通过产物分析说明水含氢、氧元素。','教师气体演示装置|干冷烧杯|检验资料','观看教师使用已验纯氢气的燃烧演示。|在火焰上方罩干冷烧杯并观察内壁。|将水滴证据与元素守恒联系，不只凭火焰颜色判断。','纯净氢气可燃烧，干冷烧杯内壁出现水滴。','氢气与氧气反应生成水，支持水由氢、氧元素组成。','2H₂+O₂ → 2H₂O（点燃）。','必须先验纯；本页只模拟纯净气体的计量，不提供混合气体点火操作。','0.04 gH₂完全燃烧生成多少水？','按4∶36，生成0.36 g水。'],{reaction:'hydrogen-burn',pepEvidence:'上册实验4-4',workedExample:calc('H₂质量0.04 g，O₂足量。','2H₂+O₂ → 2H₂O（点燃），H₂与水质量比4∶36。','m(水)=0.04×36/4=0.36 g。','理论生成0.36 g水；其中0.32 g来自氧气。'),safety:['由教师使用已验纯的氢气演示；学生不操作氢氧混合气体点火。']});
add('magnesium-mass',5,'镁燃烧后的固体增重与质量守恒','reaction',reactionControls('Mg质量','O₂质量',.48,.32),['解释开放体系固体质量增加的来源。','教师镁燃烧演示资料|坩埚|天平|氧气计量模型','比较反应前镁与反应后固体质量。|考虑来自空气的反应物和逸散的烟尘。|用纯氧模型检验完整体系的质量守恒。','镁燃烧发出耀眼白光并生成白色固体。|若氧化镁完全保留，其质量大于消耗的镁。','固体增重来自参加反应的氧气，完整反应体系仍质量守恒。','2Mg+O₂ → 2MgO；48 gMg与32 gO₂生成80 gMgO。','真实空气中可能出现氮化物并有烟尘损失，不能将简化纯氧结果当作真实称量。','0.48 gMg完全反应并保留全部MgO，固体增加多少？','吸收0.32 gO₂，生成0.80 gMgO，增加0.32 g。'],{reaction:'magnesium-burn',directoryNumbers:[35],pepEvidence:'上册实验5-2',workedExample:calc('Mg质量0.48 g，在氧气充足且无损失条件下完全反应。','2Mg+O₂ → 2MgO；48∶32∶80。','m(MgO)=0.48×80/48=0.80 g；增重=0.80−0.48=0.32 g。','固体增加0.32 g，等于反应消耗氧气质量。'),modelNote:'只计纯氧中生成MgO的理想反应；空气副反应、烟尘损失和真实点火过程不在模型内。',safety:['由教师少量演示，不直视耀眼燃烧强光。']});
add('reagent-taking',1,'固体药品与液体药品的规范取用','reagent-taking',[pick('form','试剂状态',[['block','块状固体'],['powder','粉末固体'],['liquid','少量液体']]),pick('operation','操作方式',[['correct','使用对应工具并缓慢转移'],['wrong','手拿、直落或污染瓶口']])],['按状态选择工具，减少污染与玻璃破损。','镊子|药匙|纸槽|试管|试剂瓶|滴管','阅读标签并确认试剂。|块状固体用镊子放入横放试管口，再缓慢竖起；粉末用药匙或纸槽送至管底。|倾倒液体时瓶塞倒放、标签朝向手心，瓶口靠近试管口；少量用滴管。|余药不放回原瓶，交指定容器处理。','规范取用能减少试剂污染与碰撞。','器材和转移方式由试剂状态、用量决定。','块状固体避免垂直直落砸裂管底；粉末避免沾管口和管壁。','胶头滴管不能平放、倒置或伸入另一试剂瓶；专用滴瓶滴管不冲洗后再放回。','为什么块状固体不能从竖直试管口直接丢入？','固体冲击可能使管底破裂，应横放送入再缓慢竖起。'],{kind:'学生实验',directoryNumbers:[6],pepEvidence:'上册实验1-3、1-4',modelNote:'操作选择练习，图示表现工具与接触位置，不替代实验室实际练习。'});

// Current lower-book page experiments, cross-checked in a secondary text preview.
add('ethanol-water',9,'乙醇与水的互溶','miscibility',[yes('mixed','已振荡混合'),pick('stage','观察阶段',[['now','刚操作后'],['rest','充分静置后']])],['观察液体溶质与水形成均一体系。','水|乙醇|试管|滴管','少量乙醇沿管壁加入水中并记录初始界面。|振荡后观察。|充分静置比较是否再次分层。','乙醇与水可互溶，充分混合后不恢复为油水式分层。','溶质可以是液体；乙醇水混合物可形成溶液。','扩散也会使初始界面逐渐消失。','未振荡时的暂时界面不表示两种液体不互溶。','充分振荡后又静置，乙醇与水会像油水那样分层吗？','通常不会；两者互溶。'],{pepEvidence:'下册实验9-3',safety:['乙醇远离火源。']});
add('copper-concentration',9,'比较不同浓度硫酸铜溶液的颜色','concentration-color',[num('salt','CuSO₄溶质质量','g',.1,5,.1,1),num('water','水质量','g',50,200,10,100),yes('samePath','用相同容器和观察深度')],['在可比观察条件下联系浓度与颜色深浅。','硫酸铜溶液|相同试管|天平|水','保持溶剂量相同，改变溶质用量。|使用相同容器和液层厚度比较颜色。|用质量分数表达浓度，不由颜色直接读数。','在规定范围、相同光程下较浓的硫酸铜溶液一般呈更深蓝色。','颜色可作浓度的定性线索；质量分数仍需由质量计算。','w=溶质质量/溶液质量×100%。','容器、光程和光照不同会影响颜色判断。','1 gCuSO₄溶于100 g水，质量分数是1%吗？','不是；应为1/(1+100)×100%≈0.990%。'],{pepEvidence:'下册实验9-7',workedExample:calc('1 gCuSO₄完全溶于100 g水。','溶液质量=溶质+溶剂；w=溶质/溶液×100%。','w=1/(1+100)×100%=0.990%。','质量分数约0.990%；蓝色深浅不能替代定量测量。'),modelNote:'输入范围内按全部溶解；蓝色只是定性示意，不是吸光度标定。'});
add('acid-properties',10,'观察盐酸与硫酸的物理性质','acid-properties',[pick('acid','酸',[['hcl','盐酸'],['sulfuric','硫酸']]),pick('strength','状态',[['concentrated','浓溶液'],['dilute','稀溶液']])],['区分挥发性、颜色和稀释前后的观察。','带标签试剂瓶|教师观察资料','阅读名称和浓度标签。|观看教师对外观与挥发性的演示记录。|比较同种酸浓、稀溶液的差别。','常见纯净盐酸和硫酸溶液通常无色。|浓盐酸挥发出的HCl遇水汽可形成白雾；浓硫酸不易挥发，常呈黏稠液体。','白雾是小液滴形成的现象，不应写成白烟。','酸的性质受浓度影响；不能靠直接嗅闻鉴别。','物理性质观察不等于可以触摸试剂。','浓盐酸瓶口白雾是什么形成的？','逸出的HCl遇空气中水汽形成盐酸小液滴。'],{pepEvidence:'下册实验10-4',modelNote:'仅观察资料与性质比较；白雾程度受湿度等条件影响，非挥发速率模型。',safety:['只观看教师资料，不直接闻浓酸或触摸试剂。']});
add('sulfuric-dehydration',10,'浓硫酸的脱水性：材料炭化现象','acid-dehydration',[pick('material','观察材料',[['paper','纸片'],['wood','木片'],['cotton','棉布']]),pick('acid','条件',[['concentrated','浓硫酸'],['dilute','稀硫酸对照']])],['从炭化现象认识浓硫酸的脱水性。','教师演示资料|纸、木、棉材料图片','比较原材料与教师演示后的外观。|记录接触浓酸部位变化。|把脱水性和吸收现成水分的吸水性区分。','含有机物材料接触浓硫酸可出现变黑、炭化。','脱水性涉及物质化学组成改变，不能理解为仅吸走表面水。','变黑炭化是化学变化线索。','本页不模拟具体反应式或炭产率；真实变化复杂。','炭化能否仅解释成材料表面的水被吸走？','不能，涉及有机物组成改变，是脱水性而非单纯吸水。'],{pepEvidence:'下册实验10-5',modelNote:'教师演示现象的定性模拟，不给出制备条件或真实炭化时间。',safety:['浓硫酸实验仅由教师在规定防护条件下演示。']});
add('sulfuric-dilution',10,'浓硫酸稀释时的操作与放热','acid-dilution',[pick('order','示意顺序',[['acid-water','酸加入水'],['water-acid','水加入酸']]),yes('stir','缓慢加入并不断搅拌')],['联系放热与局部温度解释规定操作。','教师演示装置图|烧杯|玻璃棒|防护用品','阅读教师演示的操作顺序。|观察稀释时的温度变化。|分析错误顺序和缺少搅拌的局部过热风险。','浓硫酸稀释会明显放热。','规定顺序有利于分散稀释放出的热，减小局部过热。','应将酸缓慢加入水并不断搅拌；不得反向。','不把平均温升等同于液面局部温度。','为什么不能把水倒进浓硫酸？','局部强烈放热可能使水迅速汽化并造成酸液飞溅。'],{pepEvidence:'下册实验10-6',modelNote:'仅操作判断与放热趋势；不编造浓酸稀释温度或热量数据。',safety:['仅观看教师演示；错误选项只显示风险解释，不作操作练习。']});
add('solution-conductivity',10,'比较不同液体的导电性','conductivity',[pick('liquid','待测液体',[['hcl','稀盐酸'],['sulfuric','稀硫酸'],['water','蒸馏水'],['ethanol','乙醇']]),yes('immersed','两电极浸入且互不接触')],['通过电学现象联系溶液中的可移动带电粒子。','低压电源|灯泡或电流指示器|电极|待测液体','以同一电路和相同电极条件比较。|电极浸入液体但不相碰。|记录是否明显导电，清洗电极后更换液体。','稀酸溶液通常明显导电。|蒸馏水、乙醇在该定性装置下通常无明显指示。','溶液导电与可自由移动的带电粒子有关。','“无明显指示”不能断言绝对没有任何电流。','电极直接相碰会短路，不能作为液体导电证据。','两种液体都无明显指示，能说明成分相同吗？','不能，导电性相近不等于物质相同。'],{pepEvidence:'下册实验10-7',modelNote:'低压电路的定性阈值示意，不虚构电导率或电流读数。',safety:['仅用规定低压教学电源，禁止接入市电。']});
add('naoh-deliquescence',10,'观察氢氧化钠的潮解','deliquescence',[yes('exposed','与空气接触'),yes('humid','空气中有水蒸气')],['区分吸水潮解与溶解放热等性质。','教师NaOH样品观察资料|表面皿|密封容器','比较暴露与密封存放条件。|记录固体表面状态。|联系保存要求与空气成分。','暴露于含水蒸气的空气中，NaOH固体可吸水并逐渐形成溶液。','潮解是吸收水蒸气后形成溶液的过程。','NaOH还可与空气中CO₂反应，保存需兼顾隔绝两者。','潮解不等于固体熔化；变化中有水进入。','NaOH敞口存放质量增大，能全归因于潮解吗？','不能，空气中CO₂参与反应也可能导致增重。'],{pepEvidence:'下册实验10-8',modelNote:'只模拟是否具备潮解条件，不预测吸水速率或质量。',safety:['不得用手接触NaOH固体或其溶液。']});
add('lime-milk',10,'氢氧化钙的微溶与石灰水、石灰乳','lime-milk',[pick('amount','加入量',[['little','少量，可全部溶解'],['excess','过量，有未溶固体']]),yes('filtered','静置后取清液或过滤')],['区分澄清石灰水与含未溶固体的石灰乳。','Ca(OH)₂|水|烧杯|玻璃棒|漏斗|滤纸','加入不同量的氢氧化钙并搅拌。|静置观察，必要时过滤。|比较清液与浑浊混合物。','Ca(OH)₂微溶于水；加入过量可见白色未溶固体。','澄清石灰水是溶液，石灰乳含悬浮固体。','不溶固体不计入溶液溶质质量。','澄清不代表没有溶质；过滤不能除掉已溶解的Ca(OH)₂。','过滤石灰乳所得清液中还有氢氧化钙吗？','有，已溶解部分能通过滤纸，仍呈碱性。'],{pepEvidence:'下册实验10-9',modelNote:'定性微溶模型，少量/过量为题设关系；不伪造溶解度数值。'});
add('copper-oxidation',8,'铜片加热后的表面变化','reaction',reactionControls('Cu质量','O₂质量',1.28,.32),['从红色铜表面变黑认识金属氧化。','教师铜片加热演示|坩埚钳|酒精灯','观察铜片原有颜色。|观看教师在空气中加热。|观察冷却后表面变黑并分析新物质。','红色铜表面生成黑色CuO。','2Cu+O₂ → 2CuO（加热）。','氧化铜的氧来自空气，完整体系质量守恒。','实际铜片通常只在表面反应，不能把全部反应理论值当作实测值。','1.28 g铜完全生成CuO，理论质量是多少？','按128∶160，为1.60 g。'],{reaction:'copper-oxidation',pepEvidence:'下册实验活动5：铜片加热',workedExample:calc('铜质量1.28 g，假设完全氧化且氧气充足。','2Cu+O₂ → 2CuO，Cu与CuO质量比128∶160。','m(CuO)=1.28×160/128=1.60 g。','理论为1.60 g；真实演示常仅表面氧化。'),safety:['由教师加热，铜片冷却前不触碰。']});
// Fixed scene modes are not exposed as ineffective one-option controls.
for(const e of list){const fixed=e.controls.filter(c=>c.options?.length===1);if(fixed.length){e.modelParams=Object.fromEntries(fixed.map(c=>[c.key,c.value]));e.controls=e.controls.filter(c=>!fixed.includes(c));}}
const byId=id=>list.find(e=>e.id==='chem-'+id);
