for(const e of list){if(e.pepEvidence)e.sourceIds.push('chem-pep-upper-scan');if(['solution','solubility','crystallization','salt-purify','sea-salt'].includes(e.model))e.sourceIds.push('chem-solubility-data');}
byId('neutralization').sourceIds.push('chem-neutral-heat');
for(const id of ['neutralization','fuel-survey'])byId(id).requiresPhysics=true;
byId('neutralization').modelNote+='反应计量与25 ℃pH由化学模型处理，给定反应热后的温升由Godot热学求解器计算。';
byId('fuel-survey').modelNote+='输入能量与损耗由Godot效率求解器按题设有效热量和效率求得。';
byId('dissolve').controls.find(c=>c.key==='solvent').options.push({value:'gasoline',label:'汽油（教师资料对照）'});
byId('dissolve').pepEvidence='下册实验9-1、9-2；另含乙醇溶剂变式';
byId('dissolve').safety.push('汽油比较仅使用教师提供的资料，远离火源，不作家庭操作。');
byId('precipitation').controls[0].options.push({value:'soda-lime',label:'Na₂CO₃与Ca(OH)₂'},{value:'barium-copper',label:'BaCl₂与CuSO₄'});
byId('precipitation').pepEvidence='下册实验10-12、10-13；另含原创比较组合';
byId('precipitation').steps=['取少量两种指定溶液。','比较Na₂CO₃与Ca(OH)₂生成白色CaCO₃，以及BaCl₂与CuSO₄生成白色BaSO₄的现象。','结合反应物和产物写出方程式；沉淀颜色不能单独区分成分。'];
byId('precipitation').examPoints.push('Na₂CO₃+Ca(OH)₂ → CaCO₃↓+2NaOH；BaCl₂+CuSO₄ → BaSO₄↓+CuCl₂。');
byId('metal-displacement').controls[0].options.push({value:'al-cu',label:'Al与CuSO₄'},{value:'cu-al',label:'Cu与Al₂(SO₄)₃'});
byId('metal-displacement').pepEvidence='下册金属与盐溶液的反应探究；保留Fe/Cu原创比较';
byId('metal-displacement').steps.push('铝丝表面先由教师按要求处理氧化膜；比较铝与硫酸铜、铜与硫酸铝。氧化膜可能使现象延迟，不能因此判铝不活泼。');
byId('metal-displacement').examPoints.push('2Al+3CuSO₄ → Al₂(SO₄)₃+3Cu；铜不能置换硫酸铝中的铝。');
